package com.yihe.framework.ehr;
import org.springframework.web.bind.annotation.*;import javax.servlet.http.*;import com.fasterxml.jackson.databind.*;import java.util.*;import java.time.*;import java.time.format.DateTimeParseException;import static com.yihe.framework.ehr.EhrAccess.*;import static com.yihe.framework.ehr.EhrController.ok;
@RestController @RequestMapping("/ehr/api/audit-logs")
public class AuditLogApi {
 private final EhrAccess access;private final EhrRepository db;private final ObjectMapper json=new ObjectMapper();
 public AuditLogApi(EhrAccess a,EhrRepository d){access=a;db=d;}
 @ModelAttribute public void headers(HttpServletResponse r){r.setHeader("Cache-Control","private, no-store");}
 private void check(boolean b,String m){if(!b)throw new EhrException(422,m);}private String s(Object x){return x==null?"":String.valueOf(x);}private EhrActor actor(HttpServletRequest r){EhrActor a=access.web(r);if(!a.doctor||a.mobile)throw new EhrException(403,"操作审计仅开放医生管理端");return a;}
 private String c(String x){return "CONVERT("+x+" USING utf8mb4) COLLATE utf8mb4_unicode_ci";}
 private String val(String x){return c("'"+x+"'");}private String jt(String x,String path){return "JSON_UNQUOTE(JSON_EXTRACT("+x+",'"+path+"'))";}
 private String sel(String source,String id,String time,String actor,String name,String role,String module,String type,String category,String content,String status,String ip,String client,String target,String correlation,String duration){return "SELECT "+val(source)+" src,"+c(id)+" id,"+time+" occurred,"+c(actor)+" actorId,"+c(name)+" actorName,"+c(role)+" actorType,"+c(module)+" moduleName,"+c(type)+" eventType,"+c(category)+" categoryCode,"+c(content)+" contentText,"+c(status)+" resultCode,"+c(ip)+" ip,"+c(client)+" clientInfo,"+c(target)+" targetId,"+c(correlation)+" correlationId,"+duration+" durationMs";}
 private static class Plan{String sql;List<Object> args=new ArrayList<>();Plan(String s,List<Object>a){sql=s;args.addAll(a);}}
 private Plan base(EhrActor a){List<Object> args=new ArrayList<>();String meta="h.redacted_diff",action="h.action",module="COALESCE("+jt(meta,"$._audit.module")+",CASE WHEN h.action REGEXP 'chronic' THEN '慢性病风险评估' WHEN h.action REGEXP 'psychological|questionnaire' THEN '心理与问卷评估' WHEN h.action REGEXP 'occupational' THEN '职业健康风险评估' WHEN h.action REGEXP 'intervention|plan' THEN '健康干预' WHEN h.action REGEXP 'report|extract|ocr' THEN '报告与档案' WHEN h.action REGEXP 'agent|ai_' THEN 'AI业务服务' ELSE '职工与健康档案' END)",type="COALESCE("+jt(meta,"$._audit.type")+",CASE WHEN h.action REGEXP 'remov|delet' THEN 'delete' WHEN h.action REGEXP 'creat|add|import' THEN 'create' WHEN h.action REGEXP 'review|confirm|reject|publish' THEN 'review' WHEN h.action REGEXP 'export|download' THEN 'export' WHEN h.action REGEXP 'ai_|agent_|ocr|extract' THEN 'invoke' ELSE 'update' END)",category="COALESCE("+jt(meta,"$._audit.category")+",CASE WHEN h.action REGEXP 'rules|template|setting|config' THEN 'config' WHEN h.action REGEXP 'ai_|agent_|ocr|extract' THEN 'ai' ELSE 'data' END)",role="COALESCE("+jt(meta,"$._audit.actorType")+",CASE WHEN u.User_Type=4 THEN '医生管理端' WHEN u.user_code IS NOT NULL THEN '后台账号' ELSE '未记录' END)";
 String archive=sel("archive","h.audit_id","DATE_ADD(h.occurred_at,INTERVAL 8 HOUR)","CONVERT(h.actor_ref USING utf8mb4)","COALESCE(u.user_name,CONVERT(h.actor_ref USING utf8mb4))",role,module,type,category,"COALESCE(NULLIF(h.reason,''),h.action)","COALESCE("+jt(meta,"$._audit.result")+",'recorded')","COALESCE("+jt(meta,"$._audit.ip")+",'')","COALESCE("+jt(meta,"$._audit.client")+",'')","COALESCE(h.record_id,h.report_id,'')","COALESCE(h.report_id,h.request_key,'')","NULL")+" FROM a_health_archive_audit_logs h LEFT JOIN yh_user_reginfo u ON "+c("u.user_code")+"="+c("CONVERT(h.actor_ref USING utf8mb4)")+" WHERE h.scope_code=? AND h.data_mode=?";args.add(a.scope);args.add(a.mode);
 String legacyStatus="CASE WHEN JSON_VALID(l.result) THEN CASE WHEN JSON_UNQUOTE(JSON_EXTRACT(l.result,'$.msg')) REGEXP '成功|success' OR JSON_UNQUOTE(JSON_EXTRACT(l.result,'$.message')) REGEXP '成功|success' THEN 'success' WHEN JSON_UNQUOTE(JSON_EXTRACT(l.result,'$.code')) IN ('1','200') THEN 'success' WHEN JSON_UNQUOTE(JSON_EXTRACT(l.result,'$.code')) REGEXP '^[4-9][0-9][0-9]$' THEN 'failed' ELSE 'unknown' END ELSE 'unknown' END";
 String legacy=sel("legacy","l.log_id","TIMESTAMPADD(SECOND,FLOOR(l.start_time/1000),'1970-01-01 08:00:00')","l.username","l.username","'原系统账号'","CASE WHEN l.description REGEXP '角色|用户|权限' THEN '用户与权限' WHEN l.description REGEXP '模板|规则|配置' THEN '业务配置' ELSE '原系统业务操作' END","CASE WHEN l.description REGEXP '删除' THEN 'delete' WHEN l.description REGEXP '新增|添加' THEN 'create' WHEN l.description REGEXP '导出|下载' THEN 'export' ELSE 'update' END","CASE WHEN l.description REGEXP '角色|用户|权限' THEN 'users' WHEN l.description REGEXP '模板|规则|配置' THEN 'config' ELSE 'data' END","COALESCE(l.description,'原系统操作记录')",legacyStatus,"COALESCE(l.ip,'')","COALESCE(l.user_agent,'')","''","COALESCE(l.uri,'')","l.spend_time")+" FROM yh_user_log l WHERE EXISTS (SELECT 1 FROM yh_user_reginfo u WHERE "+c("u.user_name")+"="+c("l.username")+" AND u.Org_Code=?) AND NOT EXISTS (SELECT 1 FROM yh_user_reginfo o WHERE "+c("o.user_name")+"="+c("l.username")+" AND (o.Org_Code IS NULL OR o.Org_Code<>?))";String org=a.scope.substring(4);args.add(org);args.add(org);
 StringBuilder union=new StringBuilder(archive).append(" UNION ALL ").append(legacy);
 for(String table:Arrays.asList("sys_logininfor","yh_loginlog")){String username=table.equals("sys_logininfor")?"l.user_name":"l.login_name";union.append(" UNION ALL ").append(sel(table.equals("sys_logininfor")?"login":"legacy-login","l.info_id","l.login_time",username,username,"'原系统账号'","'登录与安全'","'login'","'users'","COALESCE(l.msg,'登录记录')","CASE l.status WHEN '0' THEN 'success' WHEN '1' THEN 'failed' ELSE 'unknown' END","COALESCE(l.ipaddr,'')","CONCAT(COALESCE(l.browser,''),' / ',COALESCE(l.os,''))","''","''","NULL")).append(" FROM ").append(table).append(" l WHERE EXISTS (SELECT 1 FROM yh_user_reginfo u WHERE ").append(c("u.user_name")).append("=").append(c(username)).append(" AND u.Org_Code=?) AND NOT EXISTS (SELECT 1 FROM yh_user_reginfo o WHERE ").append(c("o.user_name")).append("=").append(c(username)).append(" AND (o.Org_Code IS NULL OR o.Org_Code<>?))");args.add(org);args.add(org);}
 String conv=" FROM a_agent_tool_logs l JOIN a_agent_turns t ON t.turn_id=l.turn_id JOIN a_agent_conversations v ON v.conversation_id=t.conversation_id LEFT JOIN yh_user_reginfo u ON "+c("u.user_code")+"="+c("v.owner_user")+" WHERE v.scope_code=? AND v.data_mode=? AND v.owner_user=? AND v.client_type='admin'";
 union.append(" UNION ALL ").append(sel("tool","l.tool_log_id","DATE_ADD(l.created_at,INTERVAL 8 HOUR)","v.owner_user","COALESCE(u.user_name,v.owner_user)","'AI数字健康师（用户发起）'","'AI工具调用'","'invoke'","'ai'","CONCAT('工具调用：',l.tool_name)","CASE WHEN l.outcome='ok' THEN 'success' ELSE 'failed' END","''","''","COALESCE(t.selected_record_id,'')","v.conversation_id","l.duration_ms")).append(conv);Collections.addAll(args,a.scope,a.mode,a.user);
 union.append(" UNION ALL ").append(sel("model","t.turn_id","DATE_ADD(t.created_at,INTERVAL 8 HOUR)","v.owner_user","COALESCE(u.user_name,v.owner_user)","'AI数字健康师（用户发起）'","'AI模型调用'","'invoke'","'ai'","CONCAT('数字健康师会话处理：',t.turn_status)","CASE t.turn_status WHEN 'completed' THEN 'success' WHEN 'failed' THEN 'failed' ELSE 'pending' END","''","''","COALESCE(t.selected_record_id,'')","v.conversation_id","TIMESTAMPDIFF(MICROSECOND,t.created_at,t.completed_at)/1000")).append(" FROM a_agent_turns t JOIN a_agent_conversations v ON v.conversation_id=t.conversation_id LEFT JOIN yh_user_reginfo u ON ").append(c("u.user_code")).append("=").append(c("v.owner_user")).append(" WHERE v.scope_code=? AND v.data_mode=? AND v.owner_user=? AND v.client_type='admin'");Collections.addAll(args,a.scope,a.mode,a.user);
 return new Plan("("+union+") events",args);}
 private int integer(String v,int def,int max){if(v==null)return def;try{int n=Integer.parseInt(v);check(n>=1&&n<=max,"分页超出允许范围");return n;}catch(NumberFormatException e){throw new EhrException(422,"分页参数无效");}}
 private Plan query(EhrActor a,Map<String,String> q){Plan p=base(a);StringBuilder where=new StringBuilder(" WHERE 1=1");String tab=q.getOrDefault("tab","operations");check(Arrays.asList("operations","login","ai","changes","sensitive").contains(tab),"日志类型无效");if(tab.equals("login"))where.append(" AND eventType='login'");if(tab.equals("ai"))where.append(" AND categoryCode='ai'");if(tab.equals("changes"))where.append(" AND eventType IN ('create','update','delete','review')");if(tab.equals("sensitive"))where.append(" AND (eventType IN ('delete','export') OR categoryCode='users')");
 for(String[] f:new String[][]{{"category","categoryCode"},{"type","eventType"},{"result","resultCode"},{"source","src"}}){String v=q.getOrDefault(f[0],"");check(v.length()<=50,"筛选参数过长");if(!v.isEmpty()){where.append(" AND ").append(f[1]).append("=?");p.args.add(v);}}
 for(String[] f:new String[][]{{"actor","actorName"},{"module","moduleName"},{"ip","ip"},{"target","targetId"}}){String v=q.getOrDefault(f[0],"").trim();check(v.length()<=150,"筛选内容过长");if(!v.isEmpty()){where.append(" AND ").append(f[1]).append(" LIKE ? ESCAPE '!'");p.args.add("%"+EhrService.like(v)+"%");}}
 String search=q.getOrDefault("query","").trim();check(search.length()<=150,"搜索内容过长");if(!search.isEmpty()){where.append(" AND (actorName LIKE ? ESCAPE '!' OR contentText LIKE ? ESCAPE '!' OR targetId LIKE ? ESCAPE '!' OR id LIKE ? ESCAPE '!')");for(int i=0;i<4;i++)p.args.add("%"+EhrService.like(search)+"%");}
 for(String key:Arrays.asList("from","to")){String v=q.getOrDefault(key,"");if(!v.isEmpty()){try{LocalDateTime parsed=LocalDateTime.parse(v.length()==10?v+(key.equals("from")?"T00:00:00":"T23:59:59"):v);where.append(" AND occurred ").append(key.equals("from")?">=":"<=").append(" ?");p.args.add(parsed.toString().replace('T',' '));}catch(DateTimeParseException e){throw new EhrException(422,"时间范围格式无效");}}}String from=q.getOrDefault("from",""),to=q.getOrDefault("to","");check(from.isEmpty()||to.isEmpty()||from.compareTo(to)<=0,"开始时间不能晚于结束时间");p.sql+=where;return p;}
 private Map<String,Object> publicRow(Map<String,Object> row){Map<String,Object> r=new LinkedHashMap<>(row);r.put("source",sourceLabel(s(r.get("src"))));r.put("timeZone",Arrays.asList("login","legacy-login").contains(s(r.get("src")))?"原系统记录时间":"北京时间 UTC+08:00");return r;}
 private String sourceLabel(String src){switch(src){case "archive":return "健康档案业务审计";case "legacy":return "原系统操作日志";case "login":return "系统登录记录";case "legacy-login":return "原业务登录记录";case "tool":return "数字健康师工具调用";case "model":return "数字健康师会话处理";default:return "未知来源";}}
 private Object list(EhrActor a,Map<String,String> q,int cap){int page=integer(q.get("page"),1,100000),limit=integer(q.get("limit"),10,cap);Plan p=query(a,q);long total=db.count("SELECT COUNT(*) FROM "+p.sql,p.args.toArray());String sort=q.getOrDefault("sort","desc");check(Arrays.asList("asc","desc").contains(sort),"排序方式无效");List<Object> args=new ArrayList<>(p.args);args.add(limit);args.add((long)(page-1)*limit);List<Map<String,Object>> rows=new ArrayList<>();for(Map<String,Object> row:db.all("SELECT * FROM "+p.sql+" ORDER BY occurred "+sort+",src "+sort+",id "+sort+" LIMIT ? OFFSET ?",args.toArray()))rows.add(publicRow(row));return map("items",rows,"total",total,"page",page,"limit",limit,"sourceNote","真实日志；缺失字段不补造。AI会话仅限当前账号，历史账号名有单位歧义的记录不纳入。","capturedAt",now()+"Z");}
 @GetMapping public Object list(HttpServletRequest req,@RequestParam Map<String,String> q){return ok(list(actor(req),q,50));}
 @GetMapping("/summary") public Object summary(HttpServletRequest req,@RequestParam Map<String,String> q){EhrActor a=actor(req);Map<String,String> all=new LinkedHashMap<>(q);all.remove("category");Plan p=query(a,all);return ok(map("categories",db.all("SELECT categoryCode code,COUNT(*) total FROM "+p.sql+" GROUP BY categoryCode",p.args.toArray()),"sources",db.all("SELECT src code,COUNT(*) total FROM "+p.sql+" GROUP BY src",p.args.toArray())));}
 private Map<String,Object> owned(EhrActor a,String source,String id){check(id.matches("[A-Za-z0-9_-]{1,96}")&&Arrays.asList("archive","legacy","login","legacy-login","tool","model").contains(source),"日志标识无效");Plan p=base(a);p.args.add(source);p.args.add(id);Map<String,Object> row=db.one("SELECT * FROM "+p.sql+" WHERE src=? AND id=?",p.args.toArray());if(row==null)throw new EhrException(404,"日志不存在或不在可查看范围内");return publicRow(row);}
 private Object parse(Object v){if(v==null)return Collections.emptyMap();try{return json.readValue(s(v),Object.class);}catch(Exception e){return map("说明","历史记录未保存可解析的结构化内容");}}
 @SuppressWarnings("unchecked") private Object scrub(Object value,int depth){if(depth>7)return "[内容层级过深]";if(value instanceof Map){Map<String,Object> result=new LinkedHashMap<>();for(Map.Entry<?,?> e:((Map<?,?>)value).entrySet()){String key=s(e.getKey());if(key.equals("_audit"))continue;result.put(key,key.toLowerCase(Locale.ROOT).matches(".*(password|passwd|token|secret|apikey|api_key|api.key|access.key|private.key|authorization|cookie|credential|phone|mobile|身份证|证件|电话).*")?"[已脱敏]":scrub(e.getValue(),depth+1));}return result;}if(value instanceof List){List<Object> out=new ArrayList<>();for(Object item:((List<?>)value).subList(0,Math.min(100,((List<?>)value).size())))out.add(scrub(item,depth+1));return out;}if(value instanceof String){String text=(String)value;if(text.length()>2000)text=text.substring(0,2000)+"…";return text.replaceAll("(?i)(Bearer\\s+)[A-Za-z0-9._~+/-]+=*","$1[已脱敏]").replaceAll("(?<![0-9])1[3-9][0-9]{9}(?![0-9])","[手机号已脱敏]");}return value;}
 private Map<String,Object> detail(EhrActor a,String src,String id){Map<String,Object> row=owned(a,src,id),params=map("说明","该来源未保存可展示的结构化请求参数"),changes=map("说明","该记录未保存变更前后值"),extra=map();if(src.equals("archive")){extra=db.one("SELECT action,record_id recordId,report_id reportId,revision,reason,redacted_diff diff FROM a_health_archive_audit_logs WHERE audit_id=?",id);Object diff=scrub(parse(extra.remove("diff")),0);params=map("档案ID",extra.get("recordId"),"报告ID",extra.get("reportId"),"报告版本",extra.get("revision"));if(diff instanceof Map){Map<String,Object> fields=new LinkedHashMap<>((Map<String,Object>)diff);Object request=fields.remove("request");if(request!=null)params.put("请求元信息",request);if(!fields.isEmpty())changes=map("来源保存的脱敏内容",fields);}else changes=map("来源保存的脱敏内容",diff);}else if(src.equals("legacy")){extra=db.one("SELECT method,uri,permissions,spend_time durationMs FROM yh_user_log WHERE log_id=?",id);params=new LinkedHashMap<>(extra);extra=map("说明","原始请求和响应可能含隐私或凭据，不在审计页回传");}else if(src.equals("tool")){extra=db.one("SELECT tool_name,arguments_json argumentsJson,outcome,turn_id turnId FROM a_agent_tool_logs WHERE tool_log_id=?",id);params=map("已记录的脱敏参数",scrub(parse(extra.remove("argumentsJson")),0));}else if(src.equals("model")){extra=db.one("SELECT turn_status,created_at,completed_at,request_key,conversation_id conversationId FROM a_agent_turns WHERE turn_id=?",id);params=map("说明","模型提示、会话正文和原始响应不在此页面回传");}else{String table=src.equals("login")?"sys_logininfor":"yh_loginlog";extra=db.one("SELECT login_location location,status,msg FROM "+table+" WHERE info_id=?",id);params=map("说明","登录凭据不记录或回传");}row.put("parameters",scrub(params,0));row.put("changes",scrub(changes,0));row.put("description",scrub(extra,0));return row;}
 @GetMapping("/{source}/{id}") public Object detail(HttpServletRequest req,@PathVariable String source,@PathVariable String id){return ok(detail(actor(req),source,id));}
 @GetMapping("/{source}/{id}/related") public Object related(HttpServletRequest req,@PathVariable String source,@PathVariable String id){EhrActor a=actor(req);Map<String,Object> selected=owned(a,source,id);String target=s(selected.get("targetId")),correlation=s(selected.get("correlationId"));if(target.isEmpty()&&correlation.isEmpty())return ok(map("items",new ArrayList<>(),"note","该记录没有可关联的业务标识"));Plan p=base(a);String predicate=!target.isEmpty()?"targetId=?":"correlationId=?";p.args.add(!target.isEmpty()?target:correlation);p.args.add(source);p.args.add(id);List<Map<String,Object>> out=new ArrayList<>();for(Map<String,Object> row:db.all("SELECT * FROM "+p.sql+" WHERE "+predicate+" AND NOT(src=? AND id=?) ORDER BY occurred DESC,src DESC,id DESC LIMIT 20",p.args.toArray()))out.add(publicRow(row));return ok(map("items",out,"note","按同一业务或关联标识查询，最多展示最近20条"));}
 @GetMapping("/export") public Object export(HttpServletRequest req,@RequestParam Map<String,String> q){EhrActor a=actor(req);Map<String,String> export=new LinkedHashMap<>(q);export.put("page","1");export.put("limit","1000");return ok(list(a,export,1000));}
}
